<?php $id=(int)($_GET['id']??0);$st=mysqli_prepare($conn,"SELECT * FROM products WHERE id=?");mysqli_stmt_bind_param($st,'i',$id);mysqli_stmt_execute($st);$p=mysqli_fetch_assoc(mysqli_stmt_get_result($st));if(!$p)die('Product not found');if($_SERVER['REQUEST_METHOD']==='POST'){$amount=max(0,(int)$_POST['amount']);$st=mysqli_prepare($conn,"UPDATE products SET stock=stock+? WHERE id=?");mysqli_stmt_bind_param($st,'ii',$amount,$id);mysqli_stmt_execute($st);header('Location: products.php');exit;} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Restock</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include __DIR__.'/../includes/admin_navbar.php';?><main class="admin-main"><div class="form-card"><h2>Restock <?php echo htmlspecialchars($p['name']);?></h2><p>Current Stock: <?php echo $p['stock'];?></p><form method="POST"><label>Quantity to Add</label><input type="number" name="amount" min="1" required><button>Add Stock</button></form></div></main></body></html>